INSERT INTO match_hypotheses VALUES(1,56,1,'Q1','D0','가르나초가 벤치 명단에도 빠진 이유','매치데이 명단 제외는 사실(에이브러햄도 제외). 부상·징계 보도 0건, 에메리 언급 0건. RotoWire 「standing in the squad is declining further」(스쿼드 내 입지가 더 떨어지고 있다)는 기자 해석.','기사(E&S·RotoWire·VAVEL)','pending','정황은 전술·서열 판단 쪽(LOW) — 1차 발언 없음',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(2,56,2,'Q2','D0','전반 에메리가 크게 화낸 이유(가설: 28′ 알리송 시뮬레이션 경고 직후 질책)','28′ 경고 사유 Simulation은 SS로 확정. 격노 대상을 적은 출처는 MOMS 하나(캐시·알리송 둘 다 언급), 시점 없음. Telegraph 16′ 코너 판정 항의 · Guardian 34′ 벤치 언쟁도 후보.','SS · 기사 · UTV(auto-caption)','pending','「시뮬레이션 직후 질책」을 지지하는 1차 근거 없음 — 후보 4개',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(3,56,3,'Q2','D0','후반 알리송→맥긴 교체는 질책·경고 관리와 연결?','교체는 46′(하프타임) · FM 사유 tactical. 기자 해석은 경고 누적 퇴장 위험 관리로 공통(Guardian · 1874 「I thought Allison was a red card risk」(알리송이 퇴장 위험이라고 봤다)).','SS · WS · FM · 기사','partial','교체 사실·시점 일치 · 사유는 「경고 관리」 서술이 우세',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(4,56,4,'H1','D0','완비사카가 마트센처럼 높고 넓게 섰고 캐시보다 많이 올라왔다','완비사카 평균 x 55.0 · 좌측 터치라인 94% · 상대 진영 62% · 패스 출발 x 62.2(캐시 43.5). 커널 공격형 윙백·Support .929, 마트센 LB 집계와 코사인 .891.','WS · SS · K','match','마트센 집계 최대 칸은 행3, 완비사카는 행1 — 마트센보다 더 높았다',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(5,56,5,'H1','D0','후반에도 높고 넓게 + 배후 침투','2H 평균 x 56.5 · 좌측 터치라인 100%(n=10). 53′ 좌측 롱 크로스 → 만잠비 슈팅. 2H 볼 소유 이벤트는 10개(1H 24)로 줄었다.','WS','match','위치는 일치 · 침투 빈도는 부분 일치(2H 표본 10)',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(6,56,6,'H2','D0','전반 알리송이 오른쪽 측면에 넓게 섰다','1H 우측 터치라인 83% · 평균 x 58.5. 커널 윙어·Balanced .857(SS). 수비 액션은 x 10~42까지 내려왔다.','WS · SS · K','match','「가끔 안쪽」은 이벤트 9%의 소수 구간',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(7,56,7,'H2','D0','캐시가 하프스페이스로 들어갔다(부수 추정)','캐시 중앙·하프스페이스 비중 20%, 우측 터치라인 80%.','WS','mismatch','추정 기각 — 사용자 후속 메모 「캐시는 높이 올라서지 않음」과 같은 결론',NULL,NULL,'reports/match-watch/2026-10-17-avl-newcastle.md 사용자 의견 대조표·D+2 당일 판정 정정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
