INSERT INTO match_hypotheses VALUES(81,55,42,NULL,'D0','경기 종료 FotMob 팀 최고 평점 = 바클리','FotMob **바클리 9.3(1위)** · 잭슨 9.07 · 음바예 8.64. SofaScore는 잭슨 9.5(1위) · 바클리 8.7. 바클리 지표: 2골(PK 1)·1도움, xG .94(PK .79), **라인 브레이킹 패스 6**, 패스 39/44, 키패스 2, 인터셉트 2·회수 4, 박스 터치 3','FM · SS','match','「자유로운 바클리」(H7)가 생산으로 이어진 근거다',NULL,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
