INSERT INTO match_hypotheses VALUES(83,55,15,'H5·H11','D1','후방 빌드업은 2-4-4 또는 3-2(GK가 CB 사이)이고, 경기 안에서 계속 바뀐다','Opta 사후 개정 이벤트(1,439→1,447건)로 재계산: 빌드업 분류 3-2 6→5 · 미분류 7→8. 「3-2일 때 CB 간격이 더 벌어진다(31.0 vs 25.3m)」는 27.4 vs 28.8m로 차이가 없어 철회.','WS 재수신(22시) · obs#1037','match','일치(경기 안 전환) 유지 → CB 간격 보조 주장만 철회',54,1037,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(84,55,17,'H6','D1','린델뢰프 = 볼 플레잉 CB·Aggressive','린델뢰프 전반 수비 성공 높이 40.8m → 38.9m(Opta 개정). UTV 전술 리뷰 「a little bit more advanced than POW … play a little bit as a CDM」(파우보다 약간 높이, CDM처럼).','WS 재수신 · UTV wnCdb0G15_I(auto-caption) · obs#1037','match','일치 유지 → 수치 약화(40.8→38.9m) · 영상과 일치로 보강',56,1037,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(85,55,26,'H10','D1','보강 — 지공에서는 좌측에 넓게, 역습·전환에서는 중앙 침투','음바예 전환 국면 인사이드 포워드·Balanced .882 → .787(1위 유지 · 전환 8터치).','WS 재수신 · K · obs#1037','match','일치 → 일치(약화) — 1위는 유지, 전환 표본 8터치',65,1037,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(86,55,1,'H1','D1','만잠비↔음바예 자리 교대가 많다','1874 라이브 「a period in the first half where Manzambi decided to go out to the left and then [Mbaye] was … playing off Jackson」(전반 한동안 만잠비가 왼쪽으로, 음바예가 잭슨 뒤 지원 공격수처럼)을 실측 2체인과 같은 그림으로 읽음.','1874 xvVFQUxGpLY(auto-caption)','partial','부분 일치 → 부분 일치(보강) — 단 D+2에서 보강 근거의 주어가 정정됨',40,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(87,55,4,'H2','D1','캐시↔맥긴 교대가 있고, 「맥긴 안쪽·캐시 터치라인」이 더 잦다','상대 하프타임 해설 「Mekin orta sahalaşıyor işte bek yüksek çıkıyor」(맥긴이 안으로 들어가면 풀백이 높이 올라간다)와 UTV 「natural width comes from your wing back in Matty Cash. So Mcin is able to just be more central」(폭은 캐시가, 맥긴은 더 중앙에)이 장면 A를 대표 그림으로 서술. 이벤트 빈도는 여전히 표본 3(A1 < B2).','Erdal Vahid 하프타임 · UTV wnCdb0G15_I(auto-caption) · Tanswell 19:28Z','partial','부분 일치 → 부분 일치(보강) — 서사는 장면 A를 지지, 빈도는 표본 3',43,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(88,55,27,'H11','D1','지공 = 2-4-4, 풀백은 터치라인에 넓게 DM 높이, 앞 4명은 좌→우 음바예·만잠비·잭슨·맥긴','빌라 팬 채널 3곳이 「완비사카 후방 3인 잔류 + 캐시 윙백」으로 묘사. 실측은 완비사카 빌드업 터치라인 95% · 평균 52.2m, 볼이 상대 1/3일 때 완비사카 67.6m(캐시 72.4m), UEFA 트래킹 40.6m ≈ 41.5m로 비대칭 없음. 해당 영상 구현 주장 REJECTED.','WS · UEFA · UTV/The Villans/1874 영상 · obs#1038','match','일치 → 일치(서사와 충돌했지만 실측 쪽 · 실측 채택)',66,1038,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(89,55,18,'H7','D1','카마라는 낮게 CB와 주고받고 바클리가 더 자유롭다','UTV: 카마라도 「more license to engage further forward … not just be that protector」(더 앞에서 끊을 권한, 단순 보호자가 아니다) · 압박은 「trigger points」형. 터키 Serbest Sekiz 「birinci kademin ikinci kademe geçtiği anda … anlık baskılarını başlatıyor」(1선에서 2선으로 넘어가는 순간 즉시 압박)로 독립 교차.','UTV wnCdb0G15_I · Serbest Sekiz(auto-caption)','match','일치 → 일치(보강)',57,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(90,55,9,'H3','D1','잭슨은 어드밴스드 포워드 지원처럼 좌우·2선까지 넓고 깊게 움직인다','에메리 UEFA 회견: 「sometime attacking more in the center or more left side or more right side today more right side」(때로 중앙, 때로 좌우 — 오늘은 오른쪽 위주).','에메리 UEFA 회견 jgZGB13_Qa0(auto-caption)','match','일치 → 일치(감독 확인)',48,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(91,55,11,'H4','D1','의도된 우측 빌드업으로 좌측 뒷공간(음바예)을 노렸다','에메리 회견·TNT·구단 인터뷰 어디에도 배치 의도(우측 빌드업) 언급 0건. 실측으로는 여전히 우측 쏠림이 없다.','BBC 「What Emery said」 · GOAL · VAVEL · tquE7w0cXLQ · jgZGB13_Qa0','mismatch','측면 불일치 유지 · 의도 D+2 재판정 → 판정 불가 유지',50,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(92,55,40,NULL,'D1','음바예 햄스트링 이상으로 교체','「쥐(cramp)」 서술 4곳(UTV·The Villans·1874·구단 라이브) · Flashscore 「Injury 15.10.2026 – ?」 신규 · Dsports.sn 「s''est arrêté net, touché physiquement」(그 자리에 멈췄다, 몸에 이상). 구단·감독 발표 0.','팬·매체 서술(D) + 집계 사이트(B) · obs#1039','partial','일치(부상 교체)·부위 대기 → 부분 일치 — 「햄스트링」 미확인, 쥐 쪽 서술 우세(D)',79,1039,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(93,55,41,NULL,'D1','바클리 햄스트링 또는 골반 이상으로 교체','허벅지 위 → 고관절(호들 TNT 「something around his hip area」(고관절 부위) · GiveMeSport) · 경련 가능성 · 구단 라이브 「he''s okay. Just a bit of ice」(괜찮다, 얼음찜질 정도).','중계 관찰 + 여러 매체 + 본인 경유(C) · obs#1039','match','일치(부상 교체)·부위 대기 → 골반(고관절) 쪽과 일치 · 경미 신호',80,1039,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(94,55,42,NULL,'D1','경기 종료 FotMob 팀 최고 평점 = 바클리','UEFA 공식 POTM은 만잠비(match.uefa.com playerOfTheMatch). FotMob 바클리 9.3 · SofaScore 잭슨 9.5.','UEFA · FM · SS','match','일치(FotMob) → 일치 · 단 UEFA 공식 POTM은 만잠비(제공사별 상이)',81,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(95,55,43,'H4','D1','에메리의 의도(H4)·부상 정도·선수 평가 회견','에메리 경기 후 회견·TNT·구단 인터뷰 반영: 「Then how we played in the first half I was not so happy」(전반 경기 내용은 만족스럽지 않았다) · 「In the second half, we correct defensively a little bit more compact」(후반에 수비를 더 콤팩트하게 수정). H4 의도·배치 언급 0. 부상은 사전 회견 대기.','BBC · GOAL · VAVEL · tquE7w0cXLQ · jgZGB13_Qa0 · obs#1040','pending','D+2 재판정 → 경기 후 회견 반영, 의도·부상은 다음 회차 대기',82,1040,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(96,55,11,'H4','D2','의도된 우측 빌드업으로 좌측 뒷공간(음바예)을 노렸다','H4를 둘로 나눔. H4a 「좌측(음바예 배후)이 주 공격 채널」은 서사 지지(D · 독립 3: Claret Villans 「Villa''s left side was the big ticket item」(핵심은 빌라 왼쪽이었다) · GOAL · Milliyet). H4b 「우측 빌드업으로 유인」은 실측 불일치 유지. 유인의 정체는 측면이 아니라 압박 유인 + 직선 전진(GOAL 「By inviting Fenerbahce to press and then exploiting the resulting spaces with direct passing」(압박을 유인한 뒤 생긴 공간을 직선 패스로 공략)).','Claret Villans · GOAL · Milliyet · obs#1044','mismatch','측면 불일치·의도 판정 불가 → H4a 서사 지지(D) / H4b 실측 불일치 유지 / 의도 판정 불가 유지(→ D+3)',91,1044,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(97,55,1,'H1','D2','만잠비↔음바예 자리 교대가 많다','D+1이 「[Mbaye] … playing off Jackson」으로 보충해 읽은 1874 자막의 주어를 정정: 같은 진행자(Dan Bardell) Roundtable 글은 「Manzambi moved towards the left before coming closer to Jackson」(만잠비가 왼쪽으로 갔다가 잭슨 가까이 붙었다)로 세컨드 스트라이커가 만잠비라고 적음. 「음바예 안쪽」을 받치는 독립 서사는 0, 실측 교대 2체인은 그대로.','Roundtable(Dan Bardell 10-15) · 1874 xvVFQUxGpLY · obs#1045','partial','부분 일치(1874 보강) → 부분 일치 유지 — 보강 근거 주어 정정(음바예→만잠비), 1874·Roundtable은 동일인이라 교차검증 아님',86,1045,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(98,55,4,'H2','D2','캐시↔맥긴 교대가 있고, 「맥긴 안쪽·캐시 터치라인」이 더 잦다','GOAL 「Deployed as a right winger, McGinn frequently dropped into midfield」(오른쪽 윙어로 배치됐지만 자주 중원으로 내려왔다) — 장면 A 방향.','GOAL 평점(Yosua Arya 10-15)','partial','부분 일치 → 부분 일치(방향 보강 · D)',87,NULL,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(99,55,40,NULL,'D2','음바예 햄스트링 이상으로 교체','FPL 공식 status a(출전 가능 · news 공란) · APS 「Mbaye est toutefois sortie sur blessure à la 79e mn.」(음바예는 다만 79분에 부상으로 나갔다 — 부위 없음) · Bardell 「cramp」. FPL 응답의 햄스트링은 루제리.','FPL · APS · Roundtable · obs#1043','partial','쥐 쪽 유지 · 햄스트링 미확인',92,1043,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(100,55,41,NULL,'D2','바클리 햄스트링 또는 골반 이상으로 교체','FPL status a · GiveMeSport 「could just as easily have been a muscular issue」(근육 문제였을 수도 있다). 장기 결장 신호 없음.','FPL · GiveMeSport · obs#1043','match','경미 신호 유지 · 출전 여부는 사전 회견 대기',93,1043,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(101,55,1,'H1','D3','만잠비↔음바예 자리 교대가 많다','에메리 사전 회견 「He''s a versatile player, he can drive, he can get into the box」(다재다능한 선수다. 운반도, 박스 침투도 한다) · 「something like the last years gave us with Morgan Rogers」(로저스가 준 것 같은 것) — 만잠비의 넓은 이동을 감독 의도 역할로 확인.','VAVEL 10-16 · obs#1047','partial','부분 일치 → 부분 일치 종결(재개: 2경기 합 교대 체인 ≥5면 일치)',97,1047,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(102,55,10,'H4','D3','카마라가 바클리보다 높다','팬 팟캐스트 「Kamara … played that little bit higher up the pitch … between him and Barkley they were sort of interchanging」(조금 더 높게 섰고 바클리와 자리를 바꿨다)는 사용자와 같은 인상이지만 이벤트 평균 x·트래킹 평균 두 실측을 넘지 못함.','Claret & Blue Podcast 4d4Ge5WVpO0(auto-caption · D) · WS · UEFA · obs#1047','mismatch','불일치 → 실측 불일치 유지 종결',49,1047,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(103,55,11,'H4','D3','의도된 우측 빌드업으로 좌측 뒷공간(음바예)을 노렸다','경기 후·사전 회견 모두 측면 설계 언급 0(질문도 없음). H4a는 독립 4(+ Claret & Blue 「left hand side is pretty good」(왼쪽이 꽤 좋았다) · 「foot race」(달리기 경주))로 서사 지지 종결.','Hayters · ESPN · VAVEL · Claret & Blue Podcast · obs#1047','mismatch','H4b 실측 불일치 종결 · 의도 판정 불가로 닫음(재개: 회견 직접 언급 또는 다음 2경기 우측 시작 ≥60%)',96,1047,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(104,55,40,NULL,'D3','음바예 햄스트링 이상으로 교체','FPL status a 유지 · 사전 회견 언급 0 · 예상 라인업 벤치(휴식 사유) · 팟캐스트 진행자 2명 「쥐」. Flashscore 이력 10-15~10-16 짧은 항목으로 닫힘.','FPL · Claret & Blue Podcast · Flashscore · obs#1046','partial','쥐 쪽 → 쥐(경미) 종결 · 사용자 「햄스트링」은 미확인으로 닫음 · T3 없음',99,1046,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(105,55,41,NULL,'D3','바클리 햄스트링 또는 골반 이상으로 교체','FPL status a→d 75% 「Unspecified injury」 · 에메리 「He played 85 minutes and was with some pain.」(85분을 뛰었고 통증이 있었다) · 팬 육안 「허벅지 앞(대퇴사두)」(auto-caption) · 「hip」은 RotoWire 재인용 1건.','FPL · Hayters/ESPN/VAVEL · Claret & Blue Podcast · obs#1046','match','경미 신호 → 경미(FPL d 75%) 종결 · 부위 「허벅지 앞 또는 고관절」(D)로 사용자 「골반」 쪽에 가깝다 · T3 없음',100,1046,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(106,55,43,'H4','D3','에메리의 의도(H4)·부상 정도·선수 평가 회견','에메리 뉴캐슬전 사전 회견(10-16)까지 읽음. 바클리 통증·당일 점검, 음바예 언급 0, H4 측면 설계 언급 0.','Hayters · ESPN · VAVEL · obs#1047','undecided','D+2 재판정(대기) → 종결 — 의도는 판정 불가로 닫음, 부상은 #40·#41 종결',95,1047,'reports/match-watch/2026-10-14-avl-fenerbahce.md 사용자 의견 대조표·D+1~D+3 재판정에서 옮김(2026-10-20 백필 · migration 109)','리포트 판정 그대로(백필) — 근거 등급은 각 행 evidence와 원문 참조','2026-10-20T10:52:28');
INSERT INTO match_hypotheses VALUES(107,56,2,'Q2','D3','전반 에메리가 크게 화낸 이유(가설: 28′ 알리송 시뮬레이션 경고 직후 질책)','Tanswell 실시간 ≈17′: 캐시에게 극도로 화남 · 알리송도 캐시 자리 미커버로 고함 / Townley: 알리송에게 격분해 다음 중단 때 불러 설명 요구','Tanswell·Townley Bluesky · Birmingham Live','partial','대상 = 캐시·알리송 둘 다(주·부 미확정 — D+2 「알리송 주」 하향) · 장면·시점(16′ 코너 판정 뒤 전환)은 유지',35,1082,'reports/match-watch/2026-10-17-avl-newcastle.md D+3 추적(2026-10-20) · 출처 원문 2026-10-17-avl-newcastle-d3-sources.md','D+3 원문 대조(직접 열람 위주) — 회견 전문 미게시 부분은 13:52 UTC 기준','2026-10-20T22:58:08');
INSERT INTO match_hypotheses VALUES(108,56,1,'Q1','D3','가르나초가 벤치 명단에도 빠진 이유','바이킹전 사전 회견(10-20) 가르나초 문답 0 · 부상·징계 보도 0','구단 공식 · Birmingham Live · 기자 SNS','undecided','판정 불가로 종결 — 서열 판단 해석(Tanswell)만 남음 · 회견 전문 게시 시 재확인',37,1082,'reports/match-watch/2026-10-17-avl-newcastle.md D+3 추적(2026-10-20) · 출처 원문 2026-10-17-avl-newcastle-d3-sources.md','D+3 원문 대조(직접 열람 위주) — 회견 전문 미게시 부분은 13:52 UTC 기준','2026-10-20T22:58:08');
